import * as THREE from 'three/webgpu';
import { texture, float, mul, add, vec3, attribute } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // Create group for element
  const group = new THREE.Group();
  group.position.copy(config.placement.position);
  group.rotation.copy(config.placement.rotation);
  group.scale.copy(config.placement.scale);

  // Load textures via context loader (cached)
  const colorTexture = ctx.textureLoader.load(config.assets.imageUrl);
  const depthTexture = ctx.textureLoader.load(config.assets.depthMapUrl);

  // Create tessellated plane geometry (64x64 segments for displacement detail)
  const geometry = new THREE.PlaneGeometry(1, 1, 64, 64);

  // Create NodeMaterial with TSL displacement
  const material = new THREE.NodeMaterial();

  // TSL displacement nodes: depth map controls Z offset
  const depthTexNode = texture(depthTexture).r;
  const displacementStrength = float(0.05);
  const displacementAmount = mul(depthTexNode, displacementStrength);
  const displacementVector = mul(displacementAmount, vec3(0, 0, 1));

  // Set material properties
  material.colorNode = texture(colorTexture);
  material.positionNode = add(
    attribute('position'),
    displacementVector
  );

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Animation timelines
  const hoverTimeline = gsap.timeline({ paused: true });
  let isHovering = false;

  // Setup interaction handlers
  group.userData.handlers = {
    onHover: (hovering) => {
      if (hovering && !isHovering) {
        isHovering = true;
        hoverTimeline.clear();
        // Rise-in: 0.15 units, power3.out, 0.7s
        hoverTimeline.to(mesh.position, {
          y: '+0.15',
          duration: 0.7,
          ease: 'power3.out'
        });
      } else if (!hovering && isHovering) {
        isHovering = false;
        hoverTimeline.clear();
        hoverTimeline.to(mesh.position, {
          y: '-=0.15',
          duration: 0.7,
          ease: 'power3.out'
        });
      }
    },
    onClick: () => {
      // Press-down effect: scale 0.97, 120ms, back.out
      gsap.to(mesh.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
        onComplete: () => {
          gsap.to(mesh.scale, {
            x: 1,
            y: 1,
            z: 1,
            duration: 0.12,
            ease: 'back.out'
          });
        }
      });

      // Emit hub-features.select event
      ctx.emit?.('hub-features.select');
    }
  };

  // Apply cinematic primitives (parallax-scroll with intensity 0.25)
  if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives && ctx.primitives[primitive.name]) {
        ctx.primitives[primitive.name](group, primitive.params);
      }
    }
  }

  // Cleanup function
  group.userData.cleanup = () => {
    hoverTimeline.kill();
    geometry.dispose();
    material.dispose();
    colorTexture.dispose();
    depthTexture.dispose();
  };

  return group;
}
